const escapeMap=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const hasCoordinates=w=>typeof w.latitude==='number'&&typeof w.longitude==='number'&&Number.isFinite(w.latitude)&&Number.isFinite(w.longitude)&&Math.abs(w.latitude)<=90&&Math.abs(w.longitude)<=180;
export function warehousePopup(w){return `<div class="warehouseMapPopup"><span class="overline">${escapeMap(w.country)||'COUNTRY NOT SET'}</span><h2>${escapeMap(w.name)}</h2><p>${escapeMap(w.location)||'Location not set'}</p><div class="popupCoordinates">${escapeMap(w.latitude)}, ${escapeMap(w.longitude)}</div><div class="popupOwner">${escapeMap(w.ownerEmail)} <span class="roleBadge">${escapeMap(w.role)}</span></div><div class="warehouseActions">${w.role!=='viewer'?`<button data-launch="${escapeMap(w.id)}">Open editor ↗</button>`:''}<button data-overview-launch="${escapeMap(w.id)}">Overview ↗</button></div>${w.role!=='viewer'?`<div class="warehouseActions secondaryPopupActions"><button data-edit-warehouse="${escapeMap(w.id)}">Edit details</button>${w.role==='owner'?`<button data-share="${escapeMap(w.id)}">Manage access</button>`:''}</div>`:''}</div>`;}
export function createWarehouseMap(container,rows,{L=globalThis.L}={}){if(!L?.map||!L?.markerClusterGroup){container.innerHTML='<p class="mapLoadError">The map could not load. Please refresh this page.</p>';return {update(){},reset(){},resize(){}};}let currentRows=rows,pendingPin=null,markers=new Map(),disposed=false;const map=L.map(container,{minZoom:0,maxZoom:19,zoomControl:true,worldCopyJump:false,maxBounds:[[-85.051129,-180],[85.051129,180]],maxBoundsViscosity:1});
let tileErrors=0;const status=()=>container.parentElement?.querySelector('.mapTileStatus');L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,minZoom:0,noWrap:true,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>'}).on('tileerror',()=>{tileErrors++;if(tileErrors>=3&&status())status().hidden=false}).on('tileload',()=>{tileErrors=0;if(status())status().hidden=true}).addTo(map);
const clusters=L.markerClusterGroup({maxClusterRadius:65,showCoverageOnHover:false,zoomToBoundsOnClick:true,spiderfyOnMaxZoom:true,removeOutsideVisibleBounds:true,animate:true,iconCreateFunction:cluster=>{const n=cluster.getChildCount();return L.divIcon({className:'warehouseCluster',html:`<span aria-label="${n} warehouses. Zoom in to explore.">${n}</span>`,iconSize:[42,42],iconAnchor:[21,21]});}});map.addLayer(clusters);
const icon=L.divIcon({className:'warehousePin',html:'<svg viewBox="0 0 32 42" aria-hidden="true"><path d="M16 1C7.7 1 1 7.7 1 16c0 11.5 15 25 15 25s15-13.5 15-25C31 7.7 24.3 1 16 1Z" fill="#536786" stroke="white" stroke-width="2"/><path d="m9 15 7-5 7 5v9H9z" fill="white"/><path d="M13 18h6v6h-6z" fill="#9eafc7"/></svg>',iconSize:[30,40],iconAnchor:[15,40],popupAnchor:[0,-35]});
function update(next){currentRows=next;pendingPin=null;markers.clear();clusters.clearLayers();for(const w of currentRows.filter(hasCoordinates)){const marker=L.marker([w.latitude,w.longitude],{icon,title:w.name,alt:`Warehouse: ${w.name}`,keyboard:true});marker.bindPopup(warehousePopup(w),{maxWidth:330,minWidth:235,autoPan:true});marker.on('click',()=>{pendingPin=w.id;const target=Math.max(map.getZoom(),14);if(map.getZoom()>=target){marker.openPopup();return}map.closePopup();map.once('moveend',()=>{if(!disposed&&pendingPin===w.id)marker.openPopup()});map.flyTo([w.latitude,w.longitude],target,{duration:.65});});markers.set(w.id,marker);clusters.addLayer(marker);}}
function reset(){pendingPin=null;map.closePopup();map.invalidateSize({pan:false});map.fitWorld({padding:[12,12],animate:false});}update(rows);reset();let observer;if(typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(()=>{if(!disposed)map.invalidateSize({pan:false})});observer.observe(container)}return {update,reset,resize(){map.invalidateSize({pan:false})},destroy(){disposed=true;observer?.disconnect();map.remove()}};}
